style.css:
@-moz-document domain("kick.com") {
/* 01. Twitch's 40px grid and 4px scanlines. */
html {
  color-scheme: dark !important;
  background-color: #0a0a0a !important;
  background-image:
    linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px,
      rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px,
      rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
}

/* Kick's design tokens also reach controls rendered in portals. */
html, body {
  --edge-font-family-regular: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  --edge-color-surface-bg-lowest: rgba(1,20,9,.93) !important;
  --edge-color-surface-bg-default: rgba(1,22,10,.75) !important;
  --edge-color-surface-bg-highest: rgba(6,46,22,.84) !important;
  --edge-color-surface-bg-overlay: rgba(2,23,11,.97) !important;
  --edge-color-surface-bg-overlay-highest: rgba(4,32,15,.97) !important;
  --edge-color-surface-bg-sunken: rgba(1,20,10,.82) !important;
  --edge-color-surface-fg-default: #d9ffe6 !important;
  --edge-color-surface-fg-subtle: #9ee5b6 !important;
  --edge-color-surface-fg-brand: #7fffac !important;
  --edge-color-surface-fg-nontext: rgba(28,240,102,.36) !important;
  --edge-color-surface-fg-decorative: rgba(32,243,107,.18) !important;
  --edge-color-neutral-bg-default: rgba(4,57,26,.88) !important;
  --edge-color-neutral-fg-default: #d9ffe6 !important;
  --edge-color-neutral-fg-subtle: #9ee5b6 !important;
  --edge-color-brand-bg-default: #00e85c !important;
  --edge-color-brand-fg-default: #001b09 !important;
  --edge-color-state-activated: rgba(4,54,27,.58) !important;
  --edge-color-state-hovered: rgba(12,91,39,.56) !important;
  --edge-color-state-pressed: rgba(10,115,43,.61) !important;
  --edge-color-glass-fg-brand: #7fffac !important;
  --edge-focusRing-outline-color-default: #00ff66 !important;
  --edge-focusRing-outline-color-inverse: #001b09 !important;
}
body, button, input, select, textarea, [role="textbox"], [contenteditable="true"] {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  font-variant-ligatures: none !important;
  font-feature-settings: "zero" 1 !important;
}
body {
  color: #d9ffe6 !important;
  scrollbar-color: rgba(0,232,92,.45) transparent;
}
body,
body [class~="group/main"] > div > [class~="bg-surface-bg-lowest"],
#main-container, #channel-content, main {
  background-color: transparent !important;
}
::selection {
  color: #f5fff7 !important;
  background-color: rgba(0,255,102,.35) !important;
}
a {
  text-decoration-color: rgba(69,255,137,.65) !important;
}

/* 02. Desktop and mobile navigation, logo and left rail. */
nav[class~="bg-surface-bg-lowest"] {
  background-color: rgba(1,20,9,.72) !important;
  box-shadow: inset 0 -1px 0 rgba(67,255,134,.42), 0 2px 14px rgba(0,255,102,.10) !important;
  backdrop-filter: blur(11px) saturate(125%) !important;
}
nav a[href="/"] img[alt="KICK Logo"] {
  filter: brightness(0) saturate(100%) invert(74%) sepia(99%) saturate(1884%) hue-rotate(85deg) brightness(108%) contrast(119%) drop-shadow(0 0 4px rgba(0,255,102,.85)) drop-shadow(0 0 12px rgba(0,255,102,.35)) !important;
}
nav form [class~="border-surface-fg-nontext"][class~="focus-within:border-focusLight"] {
  background-color: rgba(4,43,20,.95) !important;
  border-color: rgba(28,240,102,.36) !important;
}
nav form [class~="border-surface-fg-nontext"][class~="focus-within:border-focusLight"]:focus-within {
  border-color: #00ff66 !important;
  box-shadow: 0 0 10px rgba(0,255,102,.21) !important;
}
nav input[data-testid="search"]:focus-visible {
  outline: none !important;
}
nav button[class~="text-white"],
nav a[class~="text-white"],
#sidebar-wrapper [data-testid^="sidebar-"][class~="text-white"] {
  color: #c0ffd5 !important;
}
#sidebar-wrapper {
  background-color: rgba(2,24,13,.28) !important;
  background-image: linear-gradient(to left,
    rgba(13,92,47,.48) 0%, rgba(4,47,25,.32) 42%, rgba(1,19,11,.52) 100%) !important;
  box-shadow: inset -2px 0 0 rgba(67,255,134,.90),
    inset -10px 0 18px -11px rgba(0,255,102,.75),
    5px 0 22px -8px rgba(0,255,102,.60) !important;
}
#sidebar-wrapper h2, #sidebar-wrapper h3 {
  color: #9ee5b6 !important;
}
#sidebar-wrapper a:hover,
#sidebar-wrapper button[data-testid^="sidebar-"]:enabled:hover,
#sidebar-wrapper [data-testid^="sidebar-"][data-state="active"],
#sidebar-wrapper [aria-current="page"] {
  --edge-color-neutral-bg-default: rgba(17,117,53,.40) !important;
  background-color: rgba(17,117,53,.40) !important;
  color: #effff4 !important;
  box-shadow: inset 2px 0 0 rgba(0,255,102,.76), 0 0 10px rgba(0,255,102,.09) !important;
}
#sidebar-wrapper [data-state="active"] svg {
  fill: #7fffac !important;
}

/* 03. Browse tabs, filters and artwork. */
[data-testid^="tab-"][data-state="active"],
[data-testid^="channel-"][data-testid$="-tab"][data-state="active"],
[data-testid^="tab-"][aria-current="page"],
[data-testid^="channel-"][data-testid$="-tab"][aria-current="page"] {
  color: #7fffac !important;
  border-bottom-color: #00ff66 !important;
  box-shadow: inset 0 -1px 0 #00ff66 !important;
}
[data-testid="content-lang-filter-button"],
#livestream_sort_by,
main [class~="group/tag"] {
  border-color: rgba(32,243,107,.18) !important;
}
main [class~="group/tag"] {
  box-shadow: inset 0 0 0 1px rgba(32,243,107,.18) !important;
}
main [class~="group/tag"]:hover {
  box-shadow: inset 0 0 0 1px rgba(45,255,118,.50) !important;
}
main [data-testid="media-card-thumbnail"],
main [data-testid="category-card-root"] > [class~="aspect-3/4"] {
  border-radius: 7px !important;
  box-shadow: 0 0 0 1px rgba(32,243,107,.18) !important;
}
main [class~="group/card"]:hover [data-testid="media-card-thumbnail"],
main [class~="group/card"]:focus-within [data-testid="media-card-thumbnail"],
main [data-testid="category-card-root"]:hover > [class~="aspect-3/4"],
main [data-testid="category-card-root"]:focus-within > [class~="aspect-3/4"] {
  box-shadow: 0 0 0 1px rgba(105,255,154,.78), 0 0 18px rgba(0,255,102,.28) !important;
}
main [class~="group/card"] [class~="bg-no-repeat"][class~="z-10"] {
  background-image: linear-gradient(to bottom,
    rgba(3,50,24,0) 48%, rgba(3,50,24,.54) 100%) !important;
}

/* 04. Player surround, stream info, channel tabs and About. */
#injected-channel-player {
  background-color: transparent !important;
}
#injected-channel-player:fullscreen {
  background-color: #000 !important;
}
#channel-content {
  background-image: linear-gradient(to bottom,
    rgba(13,92,47,.48), rgba(4,47,25,.24) 95px, rgba(1,19,11,0) 245px) !important;
  box-shadow: inset 0 2px 0 rgba(67,255,134,.90),
    inset 0 10px 18px -11px rgba(0,255,102,.75) !important;
}
#channel-content > [class~="sticky"] > [class~="snap-mandatory"] {
  background-color: rgba(1,20,9,.85) !important;
  box-shadow: inset 0 -1px 0 rgba(67,255,134,.62), 0 5px 18px -9px rgba(0,255,102,.48) !important;
  backdrop-filter: blur(8px) !important;
}
#channel-content [data-testid="channel-username"],
#channel-content [data-testid="livestream-title"] {
  color: #d9ffe6 !important;
}
#channel-content section[class~="lg:bg-surface-bg-default"] {
  background-color: transparent !important;
  background-image: linear-gradient(to bottom,
    rgba(13,92,47,.43), rgba(4,47,25,.24) 65px, rgba(1,19,11,0) 155px) !important;
  box-shadow: inset 0 2px 0 rgba(67,255,134,.82),
    inset 0 10px 18px -11px rgba(0,255,102,.66) !important;
}
#channel-content button:hover > div > [class~="rounded-full"],
#channel-content button:focus-visible > div > [class~="rounded-full"] {
  border-color: #7fffac !important;
  box-shadow: 0 0 0 1px rgba(105,255,154,.78), 0 0 16px rgba(0,255,102,.35) !important;
}

/* 05. Right rail, pinned messages and chat composer. */
#channel-chatroom,
[data-testid="chatroom"] {
  background-color: rgba(2,24,13,.28) !important;
  background-image: linear-gradient(to right,
    rgba(13,92,47,.48) 0%, rgba(4,47,25,.32) 42%, rgba(1,19,11,.52) 100%) !important;
  border-left-color: rgba(67,255,134,.90) !important;
  box-shadow: inset 2px 0 0 rgba(67,255,134,.90),
    inset 10px 0 18px -11px rgba(0,255,102,.75),
    -5px 0 22px -8px rgba(0,255,102,.60) !important;
}
#channel-chatroom [data-testid="chatroom"],
#channel-chatroom > div[class~="bg-surface-bg-lowest"],
#channel-chatroom div[class~="overflow-hidden"][class~="grow"][class~="bg-surface-bg-lowest"],
#chatroom-messages,
[data-testid="chatroom-messages"] {
  background: transparent !important;
}
#channel-chatroom [data-testid="chatroom"] {
  box-shadow: none !important;
}
#channel-chatroom > div > div:first-child {
  border-bottom-color: rgba(24,241,106,.22) !important;
}
#chatroom-messages [class~="betterhover:group-hover:bg-surface-bg-highest"] {
  --edge-color-surface-bg-highest: rgba(12,91,39,.56) !important;
}
#channel-chatroom [data-testid="pinned-message-modal"] > div {
  background-color: rgba(4,54,27,.74) !important;
  box-shadow: inset 2px 0 0 rgba(0,255,102,.76) !important;
}
#chatroom-footer {
  box-shadow: inset 0 1px 0 rgba(32,243,107,.18) !important;
}
#chat-input-wrapper {
  background-color: rgba(4,43,20,.95) !important;
  border-color: rgba(28,240,102,.36) !important;
  box-shadow: inset 0 0 0 1px rgba(28,240,102,.26) !important;
}
#chat-input-wrapper:focus-within {
  --tw-ring-color: #00ff66 !important;
  border-color: #00ff66 !important;
  box-shadow: inset 0 0 0 1px #00ff66, 0 0 10px rgba(0,255,102,.21) !important;
}
#chat-input, [data-testid="chat-input"] {
  color: #effff3 !important;
  caret-color: #00ff66 !important;
}

/* 06. Forms, actions and floating menus. */
input, textarea, select, [contenteditable="true"] {
  caret-color: #00ff66 !important;
}
input[type="checkbox"], input[type="radio"], input[type="range"] {
  accent-color: #00e85c !important;
}
input[type="email"], input[type="password"],
input[autocomplete="username"] {
  background-color: rgba(4,43,20,.95) !important;
  color: #effff3 !important;
  border-color: rgba(28,240,102,.36) !important;
}
input::placeholder, textarea::placeholder {
  color: #9ee5b6 !important;
  opacity: 1 !important;
}
button:focus-visible, a:focus-visible, [role="button"]:focus-visible,
input:focus-visible, textarea:focus-visible, select:focus-visible,
[role="menuitem"]:focus-visible, [contenteditable="true"]:focus-visible {
  outline: 2px solid #00ff66 !important;
  outline-offset: 2px !important;
}
button[class~="bg-brand-bg-default"]:enabled:hover,
button[class~="bg-primary-base"]:enabled:hover {
  --edge-color-brand-bg-default: #38ff87 !important;
  box-shadow: 0 0 13px rgba(0,255,102,.32) !important;
}
[role="dialog"], [role="alertdialog"],
[role="menu"], [role="listbox"], [data-state="open"][data-side] {
  background-color: rgba(2,23,11,.97) !important;
  border-color: rgba(28,240,102,.36) !important;
  color: #d9ffe6 !important;
  box-shadow: inset 0 0 0 1px rgba(34,255,112,.36),
    0 14px 38px rgba(0,0,0,.57), 0 0 18px rgba(37,255,110,.14) !important;
}
[role="tooltip"] {
  background-color: rgba(1,20,10,.97) !important;
  color: #d9ffe6 !important;
  box-shadow: inset 0 0 0 1px rgba(32,243,107,.24) !important;
}
[role="menuitem"][data-highlighted],
[role="option"][data-highlighted],
[role="option"][aria-selected="true"] {
  background-color: rgba(12,91,39,.56) !important;
  color: #effff4 !important;
}
}
